import fs from 'fs';
import os from 'os';
import path from 'path';
import zlib from 'zlib';

function zstdAll(buf){const M=Buffer.from([0x28,0xb5,0x2f,0xfd]);const idxs=[];for(let i=0;(i=buf.indexOf(M,i))>=0;i+=4)idxs.push(i);if(idxs.length<=1){try{return zlib.zstdDecompressSync(buf).toString('utf8')}catch{return''}}let o='';for(let k=0;k<idxs.length;k++){const s=idxs[k],e=k+1<idxs.length?idxs[k+1]:buf.length;try{o+=zlib.zstdDecompressSync(buf.subarray(s,e)).toString('utf8')}catch{}}return o}

const cacheDir=path.join(os.homedir(),'.dsh','storages','session_projcache','sessions');
const DAY=86400000,tz=8*3600000,now=Date.now();
const dayStart=Math.floor((now+tz)/DAY)*DAY-tz;

// ---- 口径统一 ----
const allFiles=fs.readdirSync(cacheDir).filter(f=>f.startsWith('session-')&&f.endsWith('.json'));
const createdToday=[], hasTodayActivity=[], withActivity=[];
for(const f of allFiles){
  let j;try{j=JSON.parse(fs.readFileSync(path.join(cacheDir,f),'utf8'))}catch{continue}
  const created=j.record?.identity?.createdAt||0;
  const ctx=j.record?.rows?.contextActivity?.val?.days||{};
  const sid=f.replace(/^session-/,'').slice(0,8);
  if(created>=dayStart)createdToday.push(sid);
  if(ctx['2026-11-12'])hasTodayActivity.push(sid);
  for(const d of Object.values(ctx))if((d.wallMs||0)>0){withActivity.push(sid);break}
}
// 818min 集合：wall 归到某天的会话（同一会话跨天会被多天计）；这里复现“今日按天wall”
let dayWall=0;const daySessionsThatDay=new Set();
for(const f of allFiles){let j;try{j=JSON.parse(fs.readFileSync(path.join(cacheDir,f),'utf8'))}catch{continue}
  const ctx=j.record?.rows?.contextActivity?.val?.days||{};
  const dd=ctx['2026-11-12'];if(dd){dayWall+=(dd.wallMs||0)/60000;if((dd.wallMs||0)>0||(dd.toolCalls||0)>0)daySessionsThatDay.add(f.replace(/^session-/,'').slice(0,8));}}
console.log('=== 口径统一 ===');
console.log(`createdToday(createdAt>=今日0点)=${createdToday.length}  hasTodayActivity(今日有contextActivity天)=${hasTodayActivity.length}  今日按天wall集合(有累计wall/toolcalls)=${daySessionsThatDay.size}  今日wall合计=${dayWall.toFixed(0)}min`);

// ---- 事件日志：orchestrate isError & 关键路径、ask_user 长尾、full抽样 ----
const base=path.join(os.homedir(),'.dsh','sessions');const logMap={};
for(const d of fs.readdirSync(base)){const dd=path.join(base,d);if(!fs.statSync(dd).isDirectory())continue;for(const s of fs.readdirSync(dd)){const p=path.join(dd,s,'session.v4.jsonl.zstd');if(fs.existsSync(p))logMap[s.replace(/^session-/,'').slice(0,8)]=p}}

const orchFail=[], orchSlowOk=[];      // isError timeout vs 300s-with-result
const askLong=[]; let askTotalMs=0, askN=0;
const fullSamples=[]; // orchestrate args op
let concurrentOrchDurMs=0; // sum of orchestrate durations that overlap with other concurrent tool in same step
for(const sid of hasTodayActivity){
  const f=logMap[sid];if(!f)continue;
  let evs=[];try{evs=zstdAll(fs.readFileSync(f)).split('\n').filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean)}catch{continue}
  const callInfo={};
  for(const ev of evs){const t=ev.type||ev.event;const d=ev.data||{};const tt=ev.time||ev.ts||ev.timestamp||d.time||d.ts;
    if(/tool\/call/.test(t||'')){const id=d.callId||d.id;const nm=d.name||d.toolName||'?';const args=d.arguments||d.args||d.input||{};
      callInfo[id]={name:nm,t:tt,args};}
    else if(/tool\/result/.test(t||'')){const id=d.toolCallId||(d.message&&d.message.toolCallId);const c=callInfo[id];if(!c||!c.t||!tt)continue;const dur=tt-c.t;
      if(c.name==='orchestrate'){
        const isErr = d.isError===true || /调用超时|Error: orchestrator/.test(JSON.stringify(d).slice(0,300));
        if(dur>=290000){ if(isErr) orchFail.push({sid,durMin:+(dur/60000).toFixed(1),op:(c.args.op)||null}); else orchSlowOk.push({sid,durMin:+(dur/60000).toFixed(1)}); }
        if(c.args.op)fullSamples.push({sid,op:c.args.op});
      }
      if(c.name==='ask_user_question'){askTotalMs+=dur;askN++;if(dur>=300000)askLong.push({sid,durMin:+(dur/60000).toFixed(1)});}
    }
  }
}
console.log('\n=== orchestrate 超时语义(isError) ===');
console.log(`真失败(>=290s且isError)=${orchFail.length}  sum上限=${orchFail.reduce((a,x)=>a+x.durMin,0).toFixed(1)}min`);
for(const x of orchFail)console.log('  FAIL',x.sid,x.durMin+'min','op='+x.op);
console.log(`慢但成功(>=290s非isError)=${orchSlowOk.length}:`,orchSlowOk.map(x=>x.sid+'='+x.durMin+'m').join(' '));
const failBySid={};for(const x of orchFail)failBySid[x.sid]=(failBySid[x.sid]||0)+1;
console.log('失败按会话:',JSON.stringify(failBySid),' 按op:',JSON.stringify(orchFail.reduce((a,x)=>{a[x.op||'?']=(a[x.op||'?']||0)+1;return a},{})));

console.log('\n=== ask_user 长尾 ===');
console.log(`ask_user 总等待=${(askTotalMs/60000).toFixed(1)}min / ${askN}次`);
const askLongSum=askLong.reduce((a,x)=>a+x.durMin,0);
console.log(`>=300s 长尾=${askLong.length}次 合计=${askLongSum.toFixed(1)}min 占ask总等待 ${(askLongSum/(askTotalMs/60000)*100).toFixed(0)}%`);
for(const x of askLong)console.log('  长尾',x.sid,x.durMin+'min');

console.log('\n=== orchestrate op 抽样分布（判误用用）===');
const opCount={};for(const x of fullSamples)opCount[x.op]=(opCount[x.op]||0)+1;
console.log(JSON.stringify(opCount));
console.log('full调用样本(前12):');for(const x of fullSamples.slice(0,12))console.log('  ',x.sid,'op='+x.op);

