tool_input.command:
Write-Output "=== :3080 监听进程 ==="
$conn = Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue
if($conn){ $conn | ForEach-Object { $p = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue; Write-Output "PID=$($_.OwningProcess) Name=$($p.ProcessName) Path=$($p.Path)" } } else { Write-Output "  无 :3080 监听（可能已断）" }
Write-Output "=== 进程命令行 ==="
$conn | ForEach-Object { (Get-CimInstance Win32_Process -Filter "ProcessId=$($_.OwningProcess)" -ErrorAction SilentlyContinue).CommandLine }

$node = "D:\nvm\nodejs\node.exe"
$bin = "D:\nvm\nodejs\node_modules\@deepseek-ai\dsh\lib\bin.js"
$wd = "D:\repository\skills"
$log = "$env:USERPROFILE\.dsh\web-restart-$(Get-Date -Format yyyyMMdd-HHmmss).log"
$new = Start-Process -FilePath $node -ArgumentList $bin, 'web' -WorkingDirectory $wd -RedirectStandardOutput $log -RedirectStandardError "$log.err" -WindowStyle Hidden -PassThru
Write-Output "新进程 PID=$($new.Id) log=$log"
$ok = $false
for($i=0;$i -lt 30;$i++){
  Start-Sleep -Seconds 1
  $c = Get-NetTCPConnection -LocalPort 3080 -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.OwningProcess -eq $new.Id }
  if($c){ $ok=$true; Write-Output ":3080 已由新进程 PID=$($new.Id) 监听 (第 $($i+1)s)"; break }
}
if(-not $ok){ Write-Output "!! 未监听，日志:"; Get-Content $log -Tail 25 -ErrorAction SilentlyContinue; Get-Content "$log.err" -Tail 25 -ErrorAction SilentlyContinue }
